        scanned_old = scanned_old or {"files": operation.get("file_inventory") or []}
        return ok_result(
            "replaced paper; old notes remain in the archive and are attributed as prior-paper notes",
            paper_id=paper_id,
            new_paper_id=operation.get("new_paper_id"),
            archive_id=archive_id,
            operation_id=operation_id,
            reused=False,
            retained_note_paths=_retained_note_paths(archive_id, scanned_old, new_paper_id=operation.get("new_paper_id")),
            next_actions=[REINDEX_ACTION],
        )
    return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, f"unrecognized replace phase {phase}", paper_id=paper_id, operation_id=operation_id)


def _recognized_staging_owner(owner: Mapping[str, Any] | None, operation: Mapping[str, Any]) -> bool:
    if owner is None or type(owner) is not dict or set(owner) != STAGING_OWNER_FIELDS:
        return False
    if owner.get("schema") != STAGING_OWNER_SCHEMA or owner.get("version") != 1:
        return False
    if owner.get("kind") != "replace" or owner.get("operation_id") != operation["operation_id"]:
        return False
    if owner.get("target_id") != operation.get("paper_id"):
        return False
    intended = f"{LIBRARY_DIRNAME}/{STAGING_DIRNAME}/{operation['operation_id']}/workspace"
    if owner.get("intended_relative_target") != intended:
        return False
    allowed = owner.get("allowed_payload_set")
    return allowed == ["workspace/", "ownership.json"]


def _known_stage_relative(relative: str) -> bool:
    if relative == "ownership.json":
        return True
    if relative == "workspace/.light-workflow/locks/workspace.lock":
        return True
    if relative.startswith("workspace/.light-transactions/") and relative.endswith(".lock"):
        name = relative[len("workspace/.light-transactions/") :]
        return HEX64.fullmatch(name[: -len(".lock")]) is not None and "/" not in name
    if relative.startswith("workspace/.light-transactions/") and relative.endswith(".owner.json"):
        name = relative[len("workspace/.light-transactions/") :]
        return "--" in name and name.endswith(".owner.json") and "/" not in name
    if relative.startswith("workspace/.light-transactions/staging/") and relative.endswith(("/source.md", "/source.json")):
        rest = relative[len("workspace/.light-transactions/staging/") :]
        parts = rest.split("/")
        return len(parts) == 2 and "--" in parts[0] and parts[1] in {"source.md", "source.json"}
    if relative.startswith("workspace/papers/"):
        rest = relative[len("workspace/papers/") :]
        parts = rest.split("/")
        return len(parts) == 2 and HEX64.fullmatch(parts[0]) is not None and parts[1] in {
            "source.md",
            "source.json",
            PRIOR_NOTES_NAME,
        }
    return False


def _stage_file_relatives(staged: Path) -> list[str] | None:
    relatives: list[str] = []
    _directories, files, problems = walk_regular_tree(staged)
    if problems:
        return None
    for rel in files:
        relatives.append(rel.replace("\\", "/"))
    return relatives


def _stage_is_fully_owned(staged: Path, operation: Mapping[str, Any]) -> bool:
    if staged.is_symlink() or not staged.is_dir():
        return False
    names = set(list_names(staged))
    if names - {"ownership.json", "workspace"}:
        return False
    owner = load_persisted_object(staged / "ownership.json")
    if not _recognized_staging_owner(owner, operation):
        return False
    workspace_dir = staged / "workspace"
    if os.path.lexists(workspace_dir) and (workspace_dir.is_symlink() or not workspace_dir.is_dir()):
        return False
    relatives = _stage_file_relatives(staged)
    if relatives is None:
        return False
    return all(_known_stage_relative(rel) for rel in relatives)


def _stage_is_pre_staging_clean(staged: Path, operation: Mapping[str, Any]) -> bool:
    if not os.path.lexists(staged):
        return True
    if not _stage_is_fully_owned(staged, operation):
        return False
    relatives = _stage_file_relatives(staged) or []
    return relatives == ["ownership.json"] or relatives == []


def _discard_owned_stage(workspace: Path, operation: Mapping[str, Any]) -> bool:
    staged = staging_dir(workspace, str(operation["operation_id"]))
    if not os.path.lexists(staged):
        return True
    if not _stage_is_fully_owned(staged, operation):
        return False
    relatives = _stage_file_relatives(staged)
    if relatives is None:
        return False
    for rel in relatives:
        child = staged / rel
        if not is_regular_file(child):
            return False
        try:
            child.unlink()
        except OSError:
            return False
    for dirpath, dirnames, filenames in os.walk(staged, topdown=False, followlinks=False):
        base = Path(dirpath)
        if filenames or any((base / name).is_symlink() for name in dirnames):
            return False
        try:
            if not list_names(base):
                base.rmdir()
        except OSError:
            if base != staged:
                return False
    return not os.path.lexists(staged)


def _settle_aborted_before_staging(workspace: Path, operation: Mapping[str, Any]) -> dict[str, Any]:
    paper_id = str(operation["paper_id"])
    digest = paper_digest(paper_id)
    live = workspace / PAPER_DIRNAME / digest
    mismatch = _live_matches_file_inventory(live, digest, list(operation["file_inventory"]), list(operation["directories"]))
    if mismatch:
        return closed(str(mismatch.get("status") or LIGHT_LIBRARY_NEEDS_RECOVERY), mismatch["message"], paper_id=paper_id, operation_id=operation["operation_id"])
    if not _complete_live(workspace, digest):
        return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "old live paper is not a complete unchanged pair", paper_id=paper_id, operation_id=operation["operation_id"])
    staged = staging_dir(workspace, str(operation["operation_id"]))
    if not _stage_is_pre_staging_clean(staged, operation):
        return closed(
            LIGHT_LIBRARY_NEEDS_RECOVERY,
            "pre-staging replacement left unrecognized stage content; the live paper and extras were preserved",
            paper_id=paper_id,
            operation_id=operation["operation_id"],
        )
    if not _discard_owned_stage(workspace, operation):
        return closed(
            LIGHT_LIBRARY_NEEDS_RECOVERY,
            "owned pre-staging state could not be safely discarded",
            paper_id=paper_id,
            operation_id=operation["operation_id"],
        )
    if os.path.lexists(archive_dir(workspace, str(operation["archive_id"])) / "paper"):
        return closed(LIGHT_LIBRARY_CONFLICT, "unexpected archive payload exists for an aborted replacement", paper_id=paper_id, operation_id=operation["operation_id"])
    operation = dict(operation)
    operation["phase"] = "complete"
    operation["outcome"] = OUTCOME_ABORTED_BEFORE_STAGING
    _write_operation(workspace, operation)
    return ok_result(
        "replacement was aborted before staging; the live paper is unchanged and no replacement occurred",
        paper_id=paper_id,
        new_paper_id=None,
        archive_id=operation["archive_id"],
        operation_id=operation["operation_id"],
        reused=False,
        replaced=False,
        outcome=OUTCOME_ABORTED_BEFORE_STAGING,
        retained_note_paths=[],
        next_actions=[],
    )


def recover_library(workspace_root: Path, *, operation_id: str | None = None) -> dict[str, Any]:
    if operation_id is not None:
        operation_id = require_hex_id(operation_id, name="operation_id")
    workspace = require_workspace(workspace_root)
    try:
        with exclusive_workspace_lock(workspace):
            return _recover_locked(workspace, operation_id=operation_id)
    except _Busy:
        return closed(LIGHT_WORKSPACE_BUSY, "another cooperating operation currently owns this workspace")


def _recover_locked(workspace: Path, *, operation_id: str | None) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    paths = iter_operation_files(workspace)
    selected: list[Path] = []
    for path in paths:
        loaded = load_persisted_object(path)
        recognized = recognized_operation(loaded, filename=path.name)
        if recognized is None:
            results.append(
                closed(
                    LIGHT_LIBRARY_INVALID,
                    "malformed or foreign operation journal was preserved",
                    path=str(path.relative_to(workspace)),
                )
            )
            continue
        if operation_id is not None and recognized["operation_id"] != operation_id:
            continue
        selected.append(path)
        results.append(_recover_one(workspace, recognized))
    if operation_id is not None and not selected:
        return closed(LIGHT_LIBRARY_INVALID, "operation_id is not a recognized journal", operation_id=operation_id, operations=results)
    failed = [item for item in results if item.get("ok") is not True]
    if failed:
        return closed(
            str(failed[0].get("status") or LIGHT_LIBRARY_NEEDS_RECOVERY),
            "one or more library operations still need attention",
            operations=results,
            next_actions=[RECOVER_ACTION],
        )
    return ok_result("inspected recognized library operations", operations=results)


def _completed_operation_state(workspace: Path, operation: Mapping[str, Any]) -> dict[str, Any]:
    kind = operation["kind"]
    paper_id = str(operation["paper_id"])
    digest = paper_digest(paper_id)
    live = workspace / PAPER_DIRNAME / digest
    archive_root = archive_dir(workspace, str(operation["archive_id"]))
    payload = is_regular_dir(archive_root / "paper")
    live_exists = os.path.lexists(live)
    outcome = operation.get("outcome")
    if live_exists and payload:
        return closed(
            LIGHT_LIBRARY_CONFLICT,
            "completed journal has both the live paper and its archive payload",
            paper_id=paper_id,
            archive_id=operation["archive_id"],
            operation_id=operation["operation_id"],
        )
    if kind == "archive" and outcome != OUTCOME_ARCHIVED:
        return closed(LIGHT_LIBRARY_INVALID, "completed archive journal has an invalid outcome", operation_id=operation["operation_id"])
    if kind == "restore" and outcome != OUTCOME_RESTORED:
        return closed(LIGHT_LIBRARY_INVALID, "completed restore journal has an invalid outcome", operation_id=operation["operation_id"])
    if outcome == OUTCOME_ABORTED_BEFORE_STAGING:
        mismatch = _live_matches_file_inventory(live, digest, list(operation["file_inventory"]), list(operation["directories"]))
        if mismatch:
            return closed(str(mismatch.get("status") or LIGHT_LIBRARY_NEEDS_RECOVERY), mismatch["message"], paper_id=paper_id, operation_id=operation["operation_id"])
        if payload or os.path.lexists(staging_dir(workspace, str(operation["operation_id"]))):
            return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "aborted-before-staging journal still has leftover replacement state", paper_id=paper_id, operation_id=operation["operation_id"])
        return ok_result(
            "replacement was aborted before staging; the live paper is unchanged and no replacement occurred",
            operation_id=operation["operation_id"],
            kind=kind,
            phase="complete",
            outcome=outcome,
            replaced=False,
            reused=True,
        )
    if kind == "replace" and outcome != OUTCOME_REPLACED:
        return closed(LIGHT_LIBRARY_INVALID, "completed replace journal has an invalid outcome", operation_id=operation["operation_id"])
    if payload:
        error = _archive_matches_operation(archive_root, operation)
        if error:
            return closed(str(error.get("status") or LIGHT_LIBRARY_NEEDS_RECOVERY), error["message"], paper_id=paper_id, operation_id=operation["operation_id"])
    return ok_result("operation is already complete", operation_id=operation["operation_id"], kind=kind, phase="complete", outcome=outcome, reused=True)


def _recover_one(workspace: Path, operation: dict[str, Any]) -> dict[str, Any]:
    if operation.get("phase") == "complete":
        return _completed_operation_state(workspace, operation)
    kind = operation.get("kind")
    paper_id = operation.get("paper_id")
    digest = paper_digest(str(paper_id)) if is_paper_id(paper_id) else None
    lock = _paper_lock(workspace, digest) if digest else None
    if digest and lock is None:
        return closed(LIGHT_WORKSPACE_BUSY, "another cooperating operation owns this paper digest", operation_id=operation["operation_id"], paper_id=paper_id)
    try:
        if kind == "archive":
            if not is_paper_id(paper_id):
                return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "archive journal is missing paper_id", operation_id=operation["operation_id"])
            return _archive_locked(workspace, str(paper_id), operation=operation)
        if kind == "restore":
            archive_id = operation.get("archive_id")
            if not is_hex_id(archive_id):
                return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "restore journal is missing archive_id", operation_id=operation["operation_id"])
            return _restore_locked(workspace, str(archive_id), operation=operation, acquire_paper_lock=False)
        if kind == "replace":
            if not is_paper_id(paper_id):
                return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "replace journal is missing paper_id", operation_id=operation["operation_id"])
            phase = operation.get("phase")
            if phase == "intent":
                return _settle_aborted_before_staging(workspace, operation)
            return _replace_forward(workspace, operation, pdf_path=None, scanned_old=None)
        return closed(LIGHT_LIBRARY_INVALID, "unrecognized operation kind was preserved", operation_id=operation.get("operation_id"))
    finally:
        if lock is not None:
            lock.release()


def library_backup_blockers(workspace: Path) -> dict[str, Any] | None:
    """Return a closed refusal if library/knowledge/PDF publication state is unsafe to back up."""
    pending = pending_operation_ids(workspace)
    if pending:
        return closed(
            LIGHT_LIBRARY_NEEDS_RECOVERY,
            "pending library operations must be recovered before backup",
            pending_operation_ids=pending,

        if refused is not None:
            return refused

    for path in exclude_set:
        exclusions.append({"path": path, "rule": _exclusion_rule(path)})
    exclusions.sort(key=lambda item: item["path"])

    extra_rows: list[dict[str, Any]] = []
    for extra in extra_outputs:
        given = require_work_path(extra, name="extra_outputs item", must_exist=True, kind="file")
        if _is_inside(given, workspace):
            return closed(LIGHT_BACKUP_INVALID, "extra_outputs path is already inside the workspace and must not be repeated")
        if given.suffix.casefold() != ".md":
            return closed(LIGHT_BACKUP_INVALID, "extra_outputs must be regular .md text files", path=str(given))
        classified = classify_text_file(given, label=str(given))
        if classified["kind"] != "ok":
            return closed(LIGHT_BACKUP_INVALID, classified.get("reason") or "extra output is not allowed text", path=str(given))
        archive_path = f"exports/external/{classified['sha256']}/{given.name}"
        if any(item["path"].casefold() == archive_path.casefold() and item["path"] != archive_path for item in files):
            return closed(LIGHT_BACKUP_CONFLICT, f"extra output collides by casefold with {archive_path}")
        if any(item["path"] == archive_path and item["sha256"] != classified["sha256"] for item in files):
            return closed(LIGHT_BACKUP_CONFLICT, f"extra output collides with a different workspace member {archive_path}")
        if all(item["path"] != archive_path for item in files):
            files.append({"path": archive_path, "size_bytes": classified["size_bytes"], "sha256": classified["sha256"]})
            total += classified["size_bytes"]
        extra_rows.append(
            {
                "original_path": str(given),
                "archive_path": archive_path,
                "restore_path": archive_path,
                "hash": classified["sha256"],
            }
        )

    files.sort(key=lambda item: item["path"])
    folded: dict[str, str] = {}
    for item in files:
        key = item["path"].casefold()
        if key in folded and folded[key] != item["path"]:
            return closed(LIGHT_BACKUP_CONFLICT, f"archive member casefold collision: {item['path']}")
        folded[key] = item["path"]
        error = validate_relpath(item["path"])
        if error:
            return closed(LIGHT_BACKUP_INVALID, error, path=item["path"])
    limit = limits_ok(len(files), total)
    if limit:
        return closed(LIGHT_BACKUP_INVALID, limit)

    extra_by_archive = {row["archive_path"]: row["original_path"] for row in extra_rows}
    contents: dict[str, bytes] = {}
    for item in files:
        archive_path = item["path"]
        if archive_path in extra_by_archive:
            source = Path(extra_by_archive[archive_path])
        elif archive_path.startswith(remap_to):
            source = workspace / f"{WORKFLOW_DIRNAME}/{SESSIONS_DIRNAME}/" / archive_path[len(remap_to) :]
        else:
            source = workspace / archive_path
        data = source.read_bytes()
        if sha256_bytes(data) != item["sha256"] or len(data) != item["size_bytes"]:
            return closed(LIGHT_BACKUP_CONFLICT, f"file changed while snapshotting {archive_path}")
        contents[archive_path] = data

    return {
        "ok": True,
        "workspace": workspace,
        "workspace_id": workspace_id,
        "files": files,
        "exclusions": exclusions,
        "extra_outputs": extra_rows,
        "restore_remaps": {f"{WORKFLOW_DIRNAME}/{SESSIONS_DIRNAME}/": remap_to},
        "contents": contents,
        "total_bytes": total,
    }


def _exclusion_rule(path: str) -> str:
    if path.startswith(INDEX_DIRNAME):
        return "rebuildable-index"
    if path.startswith(TRANSACTIONS_DIR):

def _extra_has_zip64(extra: bytes) -> bool:
    offset = 0
    while offset + 4 <= len(extra):
        header_id, size = struct.unpack_from("<HH", extra, offset)
        offset += 4
        if header_id == 0x0001:
            return True
        offset += size
        if offset > len(extra):
            return True
    return False


def _inspect_zip_container(data: bytes) -> str | None:
    if len(data) < 22:
        return "archive is not a valid ZIP"
    search = data[-(65535 + 22) :] if len(data) > 65535 + 22 else data
    pos = search.rfind(b"PK\x05\x06")
    if pos < 0:
        return "archive is missing a standard end-of-central-directory"
    eocd_off = len(data) - len(search) + pos
    disk, disk_cd, nthis, ntotal, cd_size, cd_off, comment_len = struct.unpack_from("<HHHHIIH", data, eocd_off + 4)
    if disk != 0 or disk_cd != 0:
        return "multi-disk ZIP archives are refused"
    if comment_len != 0:
        return "ZIP comments are refused"
    if eocd_off + 22 + comment_len != len(data):
        return "ZIP trailing bytes are refused"
    if nthis == 0xFFFF or ntotal == 0xFFFF or cd_size == 0xFFFFFFFF or cd_off == 0xFFFFFFFF:
        return "ZIP64 metadata is refused"
    if eocd_off >= 20 and data[eocd_off - 20 : eocd_off - 16] == b"PK\x06\x07":
        return "ZIP64 metadata is refused"
    if b"PK\x06\x06" in data[max(0, eocd_off - 56) : eocd_off]:
        return "ZIP64 metadata is refused"
    if cd_off + cd_size != eocd_off:
        return "ZIP central directory is not contiguous with EOCD"
    cursor = cd_off
    local_offsets: list[int] = []
    for _ in range(ntotal):
        if cursor + 46 > len(data) or data[cursor : cursor + 4] != b"PK\x01\x02":
            return "ZIP central directory entry is malformed"
        (
            _made,
            needed,
            flags,
            method,
            mtime,
            mdate,
            _crc,
            csize,
            usize,
            name_len,
            extra_len,
            comment_len_c,
            disk_start,
            _internal,
            external,
            local_off,
        ) = struct.unpack_from("<HHHHHHIIIHHHHHII", data, cursor + 4)
        if needed >= 45 or flags & 0x1 or method != 0 or disk_start != 0:
            return "ZIP64, encrypted, or compressed members are refused"
        if mtime != 0 or mdate != 0x0021:
            return "member timestamp must be 1980-01-01 00:00:00"
        if csize == 0xFFFFFFFF or usize == 0xFFFFFFFF or local_off == 0xFFFFFFFF:
            return "ZIP64 metadata is refused"
        extra = data[cursor + 46 + name_len : cursor + 46 + name_len + extra_len]
        comment = data[cursor + 46 + name_len + extra_len : cursor + 46 + name_len + extra_len + comment_len_c]
        if extra or comment or _extra_has_zip64(extra):
            return "ZIP extra fields and comments are refused"
        if external != ZIP_EXTERNAL_ATTR:
            return "ZIP member attributes must be private regular files"
        local_offsets.append(local_off)
        cursor += 46 + name_len + extra_len + comment_len_c
    if cursor != eocd_off:
        return "ZIP central directory size is inconsistent"
    for local_off in local_offsets:
        if local_off + 30 > len(data) or data[local_off : local_off + 4] != b"PK\x03\x04":
            return "ZIP local header is malformed"
        needed, flags, method, mtime, mdate, _crc, csize, usize, name_len, extra_len = struct.unpack_from(
            "<HHHHHIIIHH", data, local_off + 4
        )
        if needed >= 45 or flags & 0x1 or method != 0:
            return "ZIP64, encrypted, or compressed members are refused"
        if mtime != 0 or mdate != 0x0021:
            return "member timestamp must be 1980-01-01 00:00:00"
        if csize == 0xFFFFFFFF or usize == 0xFFFFFFFF:
            return "ZIP64 metadata is refused"
        extra = data[local_off + 30 + name_len : local_off + 30 + name_len + extra_len]
        if extra or _extra_has_zip64(extra):
            return "ZIP extra fields and comments are refused"
    return None


def _safe_original_root_syntax(value: object) -> bool:
    if type(value) is not str or not value or "\x00" in value:
        return False
    return value == value.strip() and "\\" not in value


def _validate_manifest_object(manifest: Mapping[str, Any], *, zip_names: list[str]) -> str | None:
    expected_keys = {
        "schema",
        "workspace_root",
        "workspace_id",
        "files",
        "exclusions",
        "extra_outputs",
        "restore_remaps",
        "manifest_sha256",
    }
    if set(manifest) != expected_keys:
        return "manifest has unknown or missing top-level fields"
    if manifest.get("schema") != BACKUP_SCHEMA:
        return "manifest schema is not video-paper-wiki.light-backup.v1"
    workspace_root = manifest.get("workspace_root")
    if not _safe_original_root_syntax(workspace_root):
        return "workspace_root must be a safe string path"
    workspace_id = manifest.get("workspace_id")
    if type(workspace_id) is not str or HEX64.fullmatch(workspace_id) is None:
        return "workspace_id must be 64 lowercase hex characters"
    if workspace_id != sha256_canonical({"workspace_root": workspace_root}):
        return "workspace_id does not match canonical {workspace_root}"
    files = manifest.get("files")
    if type(files) is not list:
        return "manifest files must be an array"
    expected_names: list[str] = []
    for item in files:
        if type(item) is not dict or set(item) != {"path", "size_bytes", "sha256"}:
            return "each file inventory row must be {path,size_bytes,sha256}"
        path = item.get("path")
        size = item.get("size_bytes")
        digest = item.get("sha256")
        if type(path) is not str or validate_relpath(path) is not None:
            return "manifest file path is unsafe"
        if type(size) is not int or type(size) is bool or size < 0 or size > MAX_FILE_BYTES:
            return f"claimed size is invalid for {path}"
        if type(digest) is not str or HEX64.fullmatch(digest) is None:
            return f"file hash is invalid for {path}"
        expected_names.append(path)
    if expected_names != sorted(expected_names) or len(expected_names) != len(set(expected_names)):
        return "manifest files must be unique and sorted by path"
    if zip_names[1:] != expected_names:
        return "ZIP members after the manifest must match the sorted file inventory"
    collision = _prefix_collisions(expected_names)
    if collision:
        return collision
    exclusions = manifest.get("exclusions")
    if type(exclusions) is not list:
        return "exclusions must be an array of {path,rule} objects"
    seen_ex: set[str] = set()
    for item in exclusions:
        if type(item) is not dict or set(item) != {"path", "rule"}:
            return "each exclusion row must be {path,rule}"
        if type(item.get("path")) is not str or type(item.get("rule")) is not str or not item["path"] or not item["rule"]:
            return "exclusion path and rule must be nonempty strings"
        if item["path"] in seen_ex:
            return "exclusions contain duplicate paths"
        seen_ex.add(item["path"])
    if [item["path"] for item in exclusions] != sorted(item["path"] for item in exclusions):
        return "exclusions must be sorted by path"
    remaps = manifest.get("restore_remaps")
    if type(remaps) is not dict or set(remaps) != {f"{WORKFLOW_DIRNAME}/{SESSIONS_DIRNAME}/"}:
        return "restore_remaps must map sessions/ to history/<workspace_id>/sessions/"
    expected_remap = f"{WORKFLOW_DIRNAME}/{HISTORY_DIRNAME}/{workspace_id}/{SESSIONS_DIRNAME}/"
    if remaps.get(f"{WORKFLOW_DIRNAME}/{SESSIONS_DIRNAME}/") != expected_remap:
        return "restore_remaps target does not match workspace_id"
    extras = manifest.get("extra_outputs")
    if type(extras) is not list:
        return "extra_outputs must be an array"
    files_by_path = {item["path"]: item for item in files}
    seen_extra: set[str] = set()
    for extra in extras:
        if type(extra) is not dict or set(extra) != {"original_path", "archive_path", "restore_path", "hash"}:
            return "each extra_outputs row must be {original_path,archive_path,restore_path,hash}"
        original = extra.get("original_path")
        archive_path = extra.get("archive_path")
        restore_path = extra.get("restore_path")
        digest = extra.get("hash")
        if not _safe_original_root_syntax(original):
            return "extra_outputs original_path is not a safe path string"
        if type(archive_path) is not str or type(restore_path) is not str or archive_path != restore_path:
            return "extra_outputs archive_path and restore_path must match"
        if validate_relpath(archive_path) is not None or Path(archive_path).suffix.casefold() != ".md":
            return "extra_outputs paths must be safe .md members"
        if type(digest) is not str or HEX64.fullmatch(digest) is None:
            return "extra_outputs hash is invalid"
        prefix = f"exports/external/{digest}/"
        if not archive_path.startswith(prefix) or archive_path.count("/") != 3:
            return "extra_outputs must map to exports/external/<sha256>/<basename>.md"
        member = files_by_path.get(archive_path)
        if member is None:
            return "extra_outputs path is not an inventory member"
        if member["sha256"] != digest:
            return "extra_outputs hash does not match the inventory member"
        if archive_path in seen_extra:
            return "extra_outputs contains duplicate archive paths"
        seen_extra.add(archive_path)
    return None


def _write_zip(path: Path, manifest: Mapping[str, Any], contents: Mapping[str, bytes]) -> bytes:
    manifest_bytes = persisted_bytes(manifest)
    with path.open("wb") as handle:
        with zipfile.ZipFile(handle, "w", compression=zipfile.ZIP_STORED, allowZip64=False) as archive:
            archive.writestr(_zip_info(MANIFEST_NAME), manifest_bytes)
            for item in manifest["files"]:
                member = item["path"]
                archive.writestr(_zip_info(member), contents[member])
    data = path.read_bytes()
    if len(data) > MAX_ZIP_BYTES:
        path.unlink()
        fail(LIGHT_BACKUP_INVALID, "backup container exceeds the 136 MiB limit")
    return data


def _open_zip(archive_path: Path) -> zipfile.ZipFile:
    if archive_path.is_symlink() or not archive_path.is_file():
        fail(LIGHT_BACKUP_INVALID, "archive_path must be a regular file")
    if file_is_hardlinked(archive_path):
        fail(LIGHT_BACKUP_INVALID, "archive_path must not be hardlinked")
    size = archive_path.stat().st_size
    if size > MAX_ZIP_BYTES:
        fail(LIGHT_BACKUP_INVALID, "backup container exceeds the 136 MiB limit")
    try:
        archive = zipfile.ZipFile(archive_path, "r", allowZip64=False)
    except zipfile.BadZipFile as exc:
        fail(LIGHT_BACKUP_INVALID, "archive is not a valid ZIP")
        raise AssertionError("unreachable") from exc
    return archive


def _member_metadata_error(info: zipfile.ZipInfo) -> str | None:
    unix_mode = (info.external_attr >> 16) & 0o170777
    if stat.S_ISLNK(unix_mode) or ((info.external_attr >> 16) & 0o170000) == 0o120000:
        return f"symlink ZIP members are refused: {info.filename}"
    if info.external_attr != ZIP_EXTERNAL_ATTR:
        return f"ZIP member attributes must be private regular files: {info.filename}"
    if info.date_time != ZIP_TIMESTAMP:
        return f"member timestamp must be 1980-01-01 00:00:00: {info.filename}"
    if info.extra != b"" or info.comment != b"" or _extra_has_zip64(info.extra):
        return f"ZIP extra fields and comments are refused: {info.filename}"
    if getattr(info, "extract_version", 0) >= 45 or getattr(info, "create_version", 0) >= 45:
        return f"ZIP64 metadata is refused: {info.filename}"
    if info.compress_type != zipfile.ZIP_STORED:
        return "archive members must use ZIP_STORED"
    if info.flag_bits & 0x1:
        return "encrypted ZIP members are refused"
    if getattr(info, "file_size", 0) > 0xFFFFFFFF or getattr(info, "compress_size", 0) > 0xFFFFFFFF:
        return "ZIP64 members are refused"
    return None


def _verify_zip(archive_path: Path) -> dict[str, Any]:
    try:
        raw_container = archive_path.read_bytes()
    except OSError:
        return closed(LIGHT_BACKUP_INVALID, "archive_path is unreadable")
    container_error = _inspect_zip_container(raw_container)
    if container_error:
        return closed(LIGHT_BACKUP_INVALID, container_error)
    archive = _open_zip(archive_path)
    try:
        infos = archive.infolist()
        if not infos:
            return closed(LIGHT_BACKUP_INVALID, "archive has no members")
        if infos[0].filename != MANIFEST_NAME:
            return closed(LIGHT_BACKUP_INVALID, "LIGHT-LIBRARY-MANIFEST.json must be the first ZIP member")
        names = [info.filename for info in infos]
        if len(names) != len(set(names)):
            return closed(LIGHT_BACKUP_INVALID, "archive contains duplicate members")
        folded = [name.casefold() for name in names]
        if len(folded) != len(set(folded)):
            return closed(LIGHT_BACKUP_INVALID, "archive contains casefold-colliding members")
        uncompressed = 0
        file_count = 0
        for info in infos:
            if info.filename.endswith("/") or info.is_dir():
                return closed(LIGHT_BACKUP_INVALID, "archive must not contain directory members")
            meta_error = _member_metadata_error(info)

            operation_id=operation["operation_id"],
        )
