    def release(self) -> None:
        if self.fd is None:
            return
        try:
            fcntl.flock(self.fd, fcntl.LOCK_UN)
        finally:
            os.close(self.fd)
            self.fd = None  # type: ignore[assignment]


def set_library_inject_hook(point: str | None, hook: Callable[[str], None] | None = None) -> None:
