LIGHT_WORKSPACE_BUSY = "LIGHT_WORKSPACE_BUSY"
LIGHT_LIBRARY_INVALID = "LIGHT_LIBRARY_INVALID"
LIGHT_LIBRARY_CONFLICT = "LIGHT_LIBRARY_CONFLICT"
LIGHT_LIBRARY_NEEDS_RECOVERY = "LIGHT_LIBRARY_NEEDS_RECOVERY"
