def file_inventory_entry(*, relative: str, path: Path) -> dict[str, Any] | dict[str, Any]:
    classified = classify_text_file(path, label=relative)
    if classified["kind"] != "ok":
        return classified
    return {
        "kind": "ok",
        "path": relative,
        "size_bytes": classified["size_bytes"],
        "sha256": classified["sha256"],
    }


