        if not is_regular_file(child) or file_is_hardlinked(child):
            return False
        try:
            child.unlink()
        except OSError:
            return False
    for rel in sorted(directories, key=lambda path: path.count("/"), reverse=True):
        child = staged / rel
        try:
            if list_names(child):
                return False
            child.rmdir()
        except OSError:
            return False
    try:
        if list_names(staged):
            return False
        staged.rmdir()
    except OSError:
        return False
    return not os.path.lexists(staged)

