    OPERATIONS_DIRNAME,
    LIBRARY_SCHEMA,
    LIGHT_LIBRARY_CONFLICT,
    LIGHT_LIBRARY_INVALID,
    LIGHT_LIBRARY_NEEDS_RECOVERY,
    LIGHT_WORKSPACE_BUSY,
    OPERATION_SCHEMA,
    OUTCOME_ABORTED_BEFORE_STAGING,
    OUTCOME_ARCHIVED,
