    ensure_library_dirs,
    exclusive_workspace_lock,
    fail,
    file_is_hardlinked,
    inventory_row,
    is_hex_id,
    is_paper_id,
    is_regular_dir,
    is_regular_file,
    iter_operation_files,
    knowledge_staging_nonempty,
    library_diagnostics,
    limits_ok,
    list_names,
    load_persisted_object,
    new_hex_id,
    normalize_tags,
    normalize_title,
    ok_result,
    operation_path,
    paper_digest,
    pending_operation_ids,
    persisted_bytes,
    posix_rel,
    recognized_operation,
    require_hex_id,
    require_paper_id,
    require_workspace,
    run_library_inject,
    sha256_bytes,
    source_from_file_inventory,
    staging_dir,
    validate_directory_inventory,
    validate_file_inventory,
    validate_stage_file_inventory,
    walk_regular_tree,
    write_bytes_atomic,
