    LOCKS_DIRNAME,
    MAX_FILE_BYTES,
    MAX_FILES,
    MAX_UNCOMPRESSED_BYTES,
    MAX_ZIP_BYTES,
    RESTORATION_SCHEMA,
    SESSIONS_DIRNAME,
    TRANSACTIONS_DIR,
    WORKFLOW_DIRNAME,
    WORKFLOW_STAGING,
    WORKSPACE_INVALID,
    WORKSPACE_LOCK_NAME,
    HEX64,
    _Busy,
    chain_has_symlink,
    classify_text_file,
    closed,
    decode_utf8_text,
    exclusive_workspace_lock,
    fail,
    file_is_hardlinked,
    has_work_component,
    is_regular_dir,
    is_regular_file,
    knowledge_staging_nonempty,
    limits_ok,
    list_names,
    looks_binary,
    ok_result,
    persisted_bytes,
